const mongoose = require("mongoose");

/**
 * One practice attempt: an aptitude test, coding assessment, technical mock
 * interview or HR round, at a chosen level. Questions are generated by the
 * AI (or taken from the built-in bank when AI is unavailable); answers are
 * scored on submit.
 *
 * `correctIndex`, `explanation` and `keyPoints` reveal answers — the controller
 * strips them from every response until the attempt is completed.
 */
// "series": fixed placement test series (config/testSeries.js), level = stage.
const ASSESSMENT_TYPES = ["aptitude", "coding", "technical", "hr", "series"];
const LEVELS = ["beginner", "intermediate", "advanced"];

const questionSchema = new mongoose.Schema(
  {
    topic: { type: String, trim: true, maxlength: 80, default: "" },
    prompt: { type: String, required: true, maxlength: 2000 },
    options: [{ type: String, maxlength: 300 }], // aptitude only
    correctIndex: { type: Number, min: 0, max: 3 }, // aptitude only
    explanation: { type: String, maxlength: 3000, default: "" }, // MCQ explanation or model answer
    keyPoints: [{ type: String, maxlength: 200 }], // built-in open-ended questions: what a good answer covers
    code: { type: String, maxlength: 3000, default: "" }, // code snippet shown with the question (coding series)
  },
  { _id: false }
);

const questionResultSchema = new mongoose.Schema(
  {
    score: { type: Number, min: 0, max: 10 },
    feedback: { type: String, maxlength: 1500, default: "" },
    idealAnswer: { type: String, maxlength: 3000, default: "" },
  },
  { _id: false }
);

const assessmentSchema = new mongoose.Schema(
  {
    userId: { type: mongoose.Schema.Types.ObjectId, ref: "Student", required: true, index: true },
    type: { type: String, enum: ASSESSMENT_TYPES, required: true },
    level: { type: String, enum: LEVELS, required: true },
    source: { type: String, enum: ["ai", "bank"], default: "ai" }, // where the questions came from
    testNo: { type: Number, min: 1, max: 10 }, // series only: Test 1-10 of the stage
    track: { type: String, enum: ["aptitude", "coding", "technical", "hr"] }, // series only: which round
    seriesBranch: { type: String, default: "" }, // technical series only: branch family used
    questions: { type: [questionSchema], default: [] },
    answers: [{ type: String, maxlength: 6000 }],
    status: { type: String, enum: ["in_progress", "completed"], default: "in_progress", index: true },

    // Results (set on submit). score is null when AI review was unavailable.
    score: { type: Number, min: 0, max: 100, default: null },
    aiReviewed: { type: Boolean, default: false },
    summary: { type: String, maxlength: 2000, default: "" },
    results: { type: [questionResultSchema], default: [] },
    strengths: [{ type: String, maxlength: 300 }],
    weaknesses: [{ type: String, maxlength: 300 }],
    improvementPlan: [
      {
        _id: false,
        title: { type: String, maxlength: 120 },
        description: { type: String, maxlength: 500 },
      },
    ],
    completedAt: { type: Date },
  },
  { timestamps: true }
);

assessmentSchema.index({ userId: 1, createdAt: -1 });

module.exports = mongoose.model("Assessment", assessmentSchema);
module.exports.ASSESSMENT_TYPES = ASSESSMENT_TYPES;
module.exports.LEVELS = LEVELS;
